def max_len_sub(arr, k):
    n = len(arr)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if arr[i - 1] == arr[i - 2]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 2][j - 1])
    return dp[n][k]

