def pancake_sort(arr):
    if len(arr) == 1:
        return arr
    pivot = arr[len(arr) - 1]
    i = 0
    while i < len(arr):
        if arr[i] < pivot:
            arr[i], arr[len(arr) - 1] = arr[len(arr) - 1], arr[i]
            arr = arr[:len(arr) - 1]
            break
        i += 1
    if arr[i] == pivot:
        arr = arr[:i] + arr[i + 1:]
    return pancake_sort(arr)

