def max_path_sum(triangle, m, n):
    # Base case
    if m == 1:
        return triangle[0][n-1]
    if n == 1:
        return max(triangle[0][0], triangle[0][1])
    # Recursive case
    return max(triangle[m-1][n-1], max_path_sum(triangle, m-1, n-1), max_path_sum(triangle, m-1, n-2))

def sum_digits_twoparts(num):
    num_str = str(num)
    num_digits = len(num_str)
    max_sum = 0
    max_part = 0
    for i in range(num_digits):
        for j in range(i+1, num_digits):
            part_sum = sum(int(num_str[i]) + int(num_str[j]))
            if part_sum > max_sum:
                max_sum = part_sum
                max_part = int(num_str[i]) + int(num_str[j])
    return max_part

def longest_subseq_with_diff_one(arr, diff):
    n = len(arr)
    dp = [[0] * (diff + 1) for _ in range(n)]
