def smallest_missing(arr, start, end):
    if start == end:
        return start + 1
    if arr[start] != arr[start - 1]:
        return start + 1
    if arr[end] != arr[end + 1]:
        return end + 1
    if arr[start] == arr[start - 1] and arr[end] == arr[end + 1]:
        return start + 1
    if arr[start] == arr[start - 1]:
        return smallest_missing(arr, start + 1, end)
    if arr[end] == arr[end + 1]:
        return smallest_missing(arr, start, end - 1)
    return start + 1

def heap_assending(arr):
    n = len(arr)
    for i in range(n//2 - 1, -1, -1):
        heapify(arr, n, i)
    for i in range(n-1, 0, -1):
        arr[0], arr[i] = arr[i], arr[0]
        heapify(arr, i, 0)
    return arr

def heapify(arr, n, i):
    largest = i
    l = 2 * i + 1
    r = 2 * i + 2
    if l < n and arr[l] > arr[largest]:
        largest = l
    if r < n and arr[r] > arr[largest]:
        largest = r
    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify(arr, n, largest)

