    if x < 0 or y < 0 or x >= len(matrix) or y >= len(matrix[0]):
        return 0
    if matrix[x][y] == 0:
        return 0
    if matrix[x][y] == 1:
        return matrix[x][y]
    matrix[x][y] = 0
    return max(get_maxgold(matrix, x - 1, y), get_maxgold(matrix, x + 1, y), get_maxgold(matrix, x, y - 1), get_maxgold(matrix, x, y + 1)) + matrix[x][y]

